import sys
from collections import deque

class T:
    __slots__ = ('v', 'l', 'r')
    def __init__(self, v=0, l=None, r=None):
        self.v = v; self.l = l; self.r = r


def build(arr):
    if not arr or arr[0] == 'n':
        return None
    root = T(int(arr[0]))
    q = deque([root])
    i = 1
    while q and i < len(arr):
        node = q.popleft()
        if i < len(arr) and arr[i] != 'n':
            node.l = T(int(arr[i])); q.append(node.l)
        i += 1
        if i < len(arr) and arr[i] != 'n':
            node.r = T(int(arr[i])); q.append(node.r)
        i += 1
    return root


def flatten_brute(root):
    pre = []
    def dfs(node):
        if not node:
            return
        pre.append(node)
        dfs(node.l)
        dfs(node.r)
    dfs(root)
    for i in range(len(pre) - 1):
        pre[i].l = None
        pre[i].r = pre[i + 1]
    return root


def chain(root):
    res = []
    while root:
        res.append(str(root.v))
        root = root.r
    return ' '.join(res)


if __name__ == '__main__':
    data = sys.stdin.read().split()
    if not data:
        sys.exit(0)
    n = int(data[0])
    root = build(data[1:1 + n])
    flatten_brute(root)
    print(chain(root))

