        i += 1
        if i < len(arr) and arr[i] != 'n':
            node.r = T(int(arr[i])); q.append(node.r)
        i += 1
    return root


def flatten_best(root):
    if not root:
        return root
    stack = [root]
    prev = None
    while stack:
        node = stack.pop()
        if prev:
            prev.l = None
            prev.r = node
        if node.r:
            stack.append(node.r)
        if node.l:
            stack.append(node.l)
        prev = node
    return root


def chain(root):
    res = []
    while root:
        res.append(str(root.v))
        root = root.r
    return ' '.join(res)


